import * as s from "../core/validation/index.js";
import type { Schema } from "../core/validation/schema.js";
import { id2Schema, type Id2 } from "./unions/id2.js";
import { status1Schema, type Status1 } from "./unions/status1.js";

export type ResponsesFunctionCall = {
  /** The type of the function tool call. Always `function_call`. @default "function_call" */
  type?: "function_call";
  /** The unique ID of the function tool call generated by the model. */
  callId: string;
  /** The name of the function to run. */
  name: string;
  /** A JSON string of the arguments to pass to the function. */
  arguments: string;
  /** The unique ID of the function tool call. */
  id?: Id2;
  /** The status of the item. One of `in_progress`, `completed`, or `incomplete`. */
  status?: Status1;
};

export const responsesFunctionCallSchema: Schema<ResponsesFunctionCall> = s.object<ResponsesFunctionCall>({
  type: s.defaulted(s.literal("function_call"), "function_call"),
  callId: s.string(),
  name: s.string(),
  arguments: s.string(),
  id: s.optional(s.lazy(() => id2Schema)),
  status: s.optional(s.lazy(() => status1Schema)),
  _keysMap: {
    callId: "call_id",
  },
});
